import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"Kernel 日报 2026-11-11","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/11.md","filePath":"notes/kernel-digest/2026/11/11.md"}'),l={name:"notes/kernel-digest/2026/11/11.md"};function n(s,e,c,d,i,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-11" tabindex="-1">Kernel 日报 2026-11-11 <a class="header-anchor" href="#kernel-日报-2026-11-11" aria-label="Permalink to &quot;Kernel 日报 2026-11-11&quot;">​</a></h1><blockquote><p>生成时间：2026-11-11T01:22:26Z｜共 58 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-11 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="fc7ece316574-·-longtime-linux-developer-steps-down-from-some-roles-due-to-patch-flood-caused-by-ai" tabindex="-1"><code>fc7ece316574</code> · <a href="https://www.phoronix.com/news/Lorenzo-Stoakes-AI-Flood" target="_blank" rel="noreferrer">Longtime Linux Developer Steps Down From Some Roles Due To Patch Flood Caused By AI</a> <a class="header-anchor" href="#fc7ece316574-·-longtime-linux-developer-steps-down-from-some-roles-due-to-patch-flood-caused-by-ai" aria-label="Permalink to &quot;`fc7ece316574` · [Longtime Linux Developer Steps Down From Some Roles Due To Patch Flood Caused By AI](https://www.phoronix.com/news/Lorenzo-Stoakes-AI-Flood)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Arm 的资深内存管理开发者 Lorenzo Stoakes（2014 年起贡献内核）宣布因 AI/LLM 生成补丁泛滥带来的噪音，将退出部分内核 reviewer 角色。这反映了 AI 生成补丁对内核维护流程的实际冲击。</p><blockquote><p><strong>学习价值</strong>：对学习者理解内核社区维护模式与 AI 冲击下的 reviewer 负担问题很有参考价值。</p></blockquote><h3 id="_7bf47f7e673a-·-patch-net-next-v1-00-15-psp-introduce-socket-less-associations" tabindex="-1"><code>7bf47f7e673a</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-1-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 00/15] psp: introduce socket-less associations</a> <a class="header-anchor" href="#_7bf47f7e673a-·-patch-net-next-v1-00-15-psp-introduce-socket-less-associations" aria-label="Permalink to &quot;`7bf47f7e673a` · [[PATCH net-next v1 00/15] psp: introduce socket-less associations](https://lore.kernel.org/all/20261111005533.6436-1-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev｜网络</em></p><p>本系列（共 15 个补丁）引入 socket-less PSP 关联，使 PSP 封装和加密可应用于转发流量，实现透明的 PSP 隧道。socket-less 关联的生命周期通过 PSP netlink family 管理，存储在小型注册表中并可通过 ID 寻址。需要用户态配合管理 tc 规则和编排密钥交换。系列还包括 tc psp action、flower 匹配、decrypted skb 处理等配套改动。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，完整阐述了 PSP 传输模式加密架构从 socket 绑定到通用化的设计演进，是理解 PSP 子系统全貌的最佳入口。</p></blockquote><h3 id="_38a87b771c9e-·-patch-v4-12-19-mm-shmem-luo-retrieve-tmpfs-files-into-a-file-created-by-userspace" tabindex="-1"><code>38a87b771c9e</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-13-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 12/19] mm/shmem_luo: Retrieve tmpfs files into a file created by userspace</a> <a class="header-anchor" href="#_38a87b771c9e-·-patch-v4-12-19-mm-shmem-luo-retrieve-tmpfs-files-into-a-file-created-by-userspace" aria-label="Permalink to &quot;`38a87b771c9e` · [[PATCH v4 12/19] mm/shmem_luo: Retrieve tmpfs files into a file created by userspace](https://lore.kernel.org/all/20261111002358.1842967-13-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm｜内存管理</em></p><p>本补丁支持将保留的 tmpfs 文件恢复到用户态在 tmpfs 挂载上创建的文件中，新增 struct liveupdate_shmem_retrieve_arg 作为 LIVEUPDATE_SESSION_RETRIEVE_FD 的参数，并用 SHMEM_LUO_FLAG_TMPFS 标记记录文件来自 tmpfs 挂载。由于旧内核的挂载在新内核中不存在，文件的路径、owner、mode、扩展属性等元数据均不保留。</p><blockquote><p><strong>学习价值</strong>：展示了 LUO 文件恢复接口如何通过用户态创建的目标文件绕过挂载点不可恢复的问题，是理解 tmpfs Live Update 设计的好例子。</p></blockquote><h3 id="_8b9cdfe472da-·-synaptics-patent-claims-stop-work-on-displaylink-drivers" tabindex="-1"><code>8b9cdfe472da</code> · <a href="https://lwn.net/Articles/1102549/" target="_blank" rel="noreferrer">[$] Synaptics patent claims stop work on DisplayLink drivers</a> <a class="header-anchor" href="#_8b9cdfe472da-·-synaptics-patent-claims-stop-work-on-displaylink-drivers" aria-label="Permalink to &quot;`8b9cdfe472da` · [[$] Synaptics patent claims stop work on DisplayLink drivers](https://lwn.net/Articles/1102549/)&quot;">​</a></h3><p><em>jzb｜lwn｜<strong>LWN 订阅文章，仅预览</strong>｜其他动态</em></p><p>开发者 Mike Lothian 尝试借助 LLM 改进 Linux 上的 DisplayLink 驱动性能，并向已被 Synaptics 收购的 DisplayLink 团队求助。然而 Synaptics 法务团队以专利侵权为由要求其停止未经授权的 DisplayLink 技术实现并发出威胁，导致相关工作停滞。</p><blockquote><p><strong>学习价值</strong>：展示了专利与法律因素如何直接影响开源驱动的开发进程，是理解内核生态非技术层面约束的好案例。</p></blockquote><h3 id="_5350b414e0aa-·-eight-more-security-issues-made-public-for-the-x-org-server-xwayland" tabindex="-1"><code>5350b414e0aa</code> · <a href="https://www.phoronix.com/news/Eight-More-XOrg-Server-Issues" target="_blank" rel="noreferrer">Eight More Security Issues Made Public For The X.Org Server / XWayland</a> <a class="header-anchor" href="#_5350b414e0aa-·-eight-more-security-issues-made-public-for-the-x-org-server-xwayland" aria-label="Permalink to &quot;`5350b414e0aa` · [Eight More Security Issues Made Public For The X.Org Server / XWayland](https://www.phoronix.com/news/Eight-More-XOrg-Server-Issues)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>在 AI/LLM 辅助下，X.Org Server 又有八个安全漏洞被公开披露，这些问题同样影响 XWayland 代码。这是近期 X.Org Server 一系列安全审计的延续。</p><blockquote><p><strong>学习价值</strong>：提醒学习者用户态图形栈的安全审计仍在持续，但内容不属于内核子系统本身。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（18 条）</li><li><strong>网络</strong>（17 条）</li><li><strong>Rust in Linux</strong>（7 条）</li><li><strong>跟踪与性能</strong>（1 条）</li><li><strong>版本发布动态</strong>（3 条）</li><li><strong>其他动态</strong>（12 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_783455ebd0db-·-patch-v3-mm-slub-genericize-x86-specific-cmpxchg16b-comment" tabindex="-1"><code>783455ebd0db</code> · <a href="https://lore.kernel.org/all/20261111011108.29311-1-yangtiezhu@loongson.cn/" target="_blank" rel="noreferrer">[PATCH v3] mm/slub: Genericize x86-specific cmpxchg16b comment</a> <a class="header-anchor" href="#_783455ebd0db-·-patch-v3-mm-slub-genericize-x86-specific-cmpxchg16b-comment" aria-label="Permalink to &quot;`783455ebd0db` · [[PATCH v3] mm/slub: Genericize x86-specific cmpxchg16b comment](https://lore.kernel.org/all/20261111011108.29311-1-yangtiezhu@loongson.cn/)&quot;">​</a></h3><p><em>Tiezhu Yang (<a href="mailto:yangtiezhu@loongson.cn" target="_blank" rel="noreferrer">yangtiezhu@loongson.cn</a>)｜lkml</em></p><p>该补丁将 mm/slub.c 中 __kmalloc_nolock_noprof() 的注释从 x86 特定的 &quot;cmpxchg16b&quot; 改为通用的 &quot;double-width atomic cmpxchg&quot;，使注释适用于 Loongson 等其他架构。这是 v3 版本，按 reviewer 要求补充了 Suggested-by 标签并精简了提交信息。</p><blockquote><p><strong>学习价值</strong>：展示了内核社区如何通过小补丁消除架构特定表述，是学习补丁迭代与 commit message 规范的好例子。</p></blockquote><h3 id="_29a48b75e98d-·-patch-v4-19-19-selftests-liveupdate-test-block-accounting-of-retrieved-tmpfs-files" tabindex="-1"><code>29a48b75e98d</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-20-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 19/19] selftests/liveupdate: Test block accounting of retrieved tmpfs files</a> <a class="header-anchor" href="#_29a48b75e98d-·-patch-v4-19-19-selftests-liveupdate-test-block-accounting-of-retrieved-tmpfs-files" aria-label="Permalink to &quot;`29a48b75e98d` · [[PATCH v4 19/19] selftests/liveupdate: Test block accounting of retrieved tmpfs files](https://lore.kernel.org/all/20261111002358.1842967-20-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 luo_tmpfs 自测添加 tmpfs 文件被 retrieve 后块计费的测试用例：验证文件恰好填满等大 mount、超出文件末尾的 large folio 会被全额计费；mount 空间或 memcg 限额耗尽时操作永久失败且不产生计费，会话仍可正常结束。测试依赖 CONFIG_TRANSPARENT_HUGEPAGE、CONFIG_CGROUPS 和 CONFIG_MEMCG，未启用时跳过。</p><blockquote><p><strong>学习价值</strong>：展示了 liveupdate 子系统中 tmpfs 块计费与 memcg 交互的边界条件测试，是学习内核测试设计的好素材。</p></blockquote><h3 id="a8b129b2fd61-·-patch-v4-18-19-selftests-liveupdate-test-retrieving-tmpfs-files-preserved-read-only" tabindex="-1"><code>a8b129b2fd61</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-19-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 18/19] selftests/liveupdate: Test retrieving tmpfs files preserved read-only</a> <a class="header-anchor" href="#a8b129b2fd61-·-patch-v4-18-19-selftests-liveupdate-test-retrieving-tmpfs-files-preserved-read-only" aria-label="Permalink to &quot;`a8b129b2fd61` · [[PATCH v4 18/19] selftests/liveupdate: Test retrieving tmpfs files preserved read-only](https://lore.kernel.org/all/20261111002358.1842967-19-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 luo_tmpfs 添加只读方式保留 tmpfs 文件的测试用例，覆盖通过只读 fd、只读 mount、只读 superblock 保留的文件以及 immutable 文件，其中稀疏文件的空洞在保留时会被填充。测试还验证保留文件的 size 被冻结，以及文件内的写入会被保留。</p><blockquote><p><strong>学习价值</strong>：帮助学习者理解 liveupdate 机制下文件只读保留的语义细节，以及稀疏文件处理方式。</p></blockquote><h3 id="a221f874b497-·-patch-v4-17-19-selftests-liveupdate-test-the-targets-of-retrieved-tmpfs-files" tabindex="-1"><code>a221f874b497</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-18-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 17/19] selftests/liveupdate: Test the targets of retrieved tmpfs files</a> <a class="header-anchor" href="#a221f874b497-·-patch-v4-17-19-selftests-liveupdate-test-the-targets-of-retrieved-tmpfs-files" aria-label="Permalink to &quot;`a221f874b497` · [[PATCH v4 17/19] selftests/liveupdate: Test the targets of retrieved tmpfs files](https://lore.kernel.org/all/20261111002358.1842967-18-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 luo_tmpfs 添加测试，验证 tmpfs 文件 retrieve 的目标文件要求：必须以写方式打开（可以是 write-only）并保留其文件状态标志；必须是 tmpfs mount 上的空普通文件，memfd、pipe、目录和 immutable 文件均被拒绝，且失败后可换文件重试。同时验证非特权进程可 retrieve 到自己创建的文件并保留 owner 和 mode。</p><blockquote><p><strong>学习价值</strong>：详细展示了内核 API 对目标文件的合法性检查设计，是学习接口约束与测试覆盖的范例。</p></blockquote><h3 id="cec5569ccf93-·-patch-v4-16-19-selftests-liveupdate-test-memfds-and-luo-interactions-in-luo-tmpfs" tabindex="-1"><code>cec5569ccf93</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-17-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 16/19] selftests/liveupdate: Test memfds and LUO interactions in luo_tmpfs</a> <a class="header-anchor" href="#cec5569ccf93-·-patch-v4-16-19-selftests-liveupdate-test-memfds-and-luo-interactions-in-luo-tmpfs" aria-label="Permalink to &quot;`cec5569ccf93` · [[PATCH v4 16/19] selftests/liveupdate: Test memfds and LUO interactions in luo_tmpfs](https://lore.kernel.org/all/20261111002358.1842967-17-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 luo_tmpfs 添加 memfd 与 LUO（liveupdate）交互的测试：memfd 被 retrieve 后仍是 memfd，保留其 seals 和文件位置，且只能不带 retrieve 参数进行；而 tmpfs 文件必须带参数。还验证无效参数可修复后重试、token 重复 retrieve 返回 -EBUSY、以及已被 LUO 管理的文件不能作为目标等规则。</p><blockquote><p><strong>学习价值</strong>：通过测试用例清晰呈现 LUO retrieve 接口的状态机与错误语义，适合学习内核接口设计。</p></blockquote><h3 id="_8e6441a5ed0d-·-patch-v4-15-19-selftests-liveupdate-add-a-test-for-retrieving-tmpfs-files" tabindex="-1"><code>8e6441a5ed0d</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-16-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 15/19] selftests/liveupdate: Add a test for retrieving tmpfs files</a> <a class="header-anchor" href="#_8e6441a5ed0d-·-patch-v4-15-19-selftests-liveupdate-add-a-test-for-retrieving-tmpfs-files" aria-label="Permalink to &quot;`8e6441a5ed0d` · [[PATCH v4 15/19] selftests/liveupdate: Add a test for retrieving tmpfs files](https://lore.kernel.org/all/20261111002358.1842967-16-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>引入 luo_tmpfs，一个基于 kexec 的 tmpfs 文件保留与 retrieve 测试：Stage 1 保留各测试用例的源文件，Stage 2 在各自独立目录和 tmpfs mount 中运行，以便用 statfs() 和 st_blocks 精确检查块使用量。首批用例验证 retrieve 后文件的内容、大小和空洞，覆盖普通文件和 O_TMPFILE 创建的文件。</p><blockquote><p><strong>学习价值</strong>：展示了如何设计基于 kexec 的多阶段内核自测框架，对学习 selftests 结构很有帮助。</p></blockquote><h3 id="_5710a9037072-·-patch-v4-14-19-selftests-liveupdate-test-which-tmpfs-files-can-be-preserved" tabindex="-1"><code>5710a9037072</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-15-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 14/19] selftests/liveupdate: Test which tmpfs files can be preserved</a> <a class="header-anchor" href="#_5710a9037072-·-patch-v4-14-19-selftests-liveupdate-test-which-tmpfs-files-can-be-preserved" aria-label="Permalink to &quot;`5710a9037072` · [[PATCH v4 14/19] selftests/liveupdate: Test which tmpfs files can be preserved](https://lore.kernel.org/all/20261111002358.1842967-15-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 liveupdate.c 添加 tmpfs 文件保留时的检查测试：文件可通过只读 fd 保留但不能通过 write-only fd；保留需要写权限（immutable 文件 owner 或只读 superblock 上的文件除外）；append-only 文件不能保留；保留后文件 size 被冻结直到 unpreserve。这些检查无需 kexec，作为常规 liveupdate 自测的一部分运行。</p><blockquote><p><strong>学习价值</strong>：通过具体权限规则测试展示 liveupdate 文件保留的安全约束，有助于理解内核权限模型的应用。</p></blockquote><h3 id="_31048fee92ff-·-patch-v4-13-19-mm-shmem-luo-allow-preserving-tmpfs-files" tabindex="-1"><code>31048fee92ff</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-14-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 13/19] mm/shmem_luo: Allow preserving tmpfs files</a> <a class="header-anchor" href="#_31048fee92ff-·-patch-v4-13-19-mm-shmem-luo-allow-preserving-tmpfs-files" aria-label="Permalink to &quot;`31048fee92ff` · [[PATCH v4 13/19] mm/shmem_luo: Allow preserving tmpfs files](https://lore.kernel.org/all/20261111002358.1842967-14-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁放宽 shmem_luo_can_preserve() 中的链接数检查，允许保留 tmpfs 挂载上的文件（而不仅是 memfd）。由于 tmpfs 文件现在可以被恢复到用户态在 tmpfs 挂载上创建的文件中，该检查已无必要。文件路径本身不被保留，用户态可自行将恢复后的文件链接到期望路径；但保留期间文件大小被冻结，会影响所有通过路径打开它的使用者。</p><blockquote><p><strong>学习价值</strong>：有助于理解 Live Update 机制中 tmpfs 文件保留的语义边界，以及文件大小冻结对共享文件者的影响。</p></blockquote><h3 id="_38a87b771c9e-·-patch-v4-12-19-mm-shmem-luo-retrieve-tmpfs-files-into-a-file-created-by-userspace-1" tabindex="-1"><code>38a87b771c9e</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-13-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 12/19] mm/shmem_luo: Retrieve tmpfs files into a file created by userspace</a> <a class="header-anchor" href="#_38a87b771c9e-·-patch-v4-12-19-mm-shmem-luo-retrieve-tmpfs-files-into-a-file-created-by-userspace-1" aria-label="Permalink to &quot;`38a87b771c9e` · [[PATCH v4 12/19] mm/shmem_luo: Retrieve tmpfs files into a file created by userspace](https://lore.kernel.org/all/20261111002358.1842967-13-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁支持将保留的 tmpfs 文件恢复到用户态在 tmpfs 挂载上创建的文件中，新增 struct liveupdate_shmem_retrieve_arg 作为 LIVEUPDATE_SESSION_RETRIEVE_FD 的参数，并用 SHMEM_LUO_FLAG_TMPFS 标记记录文件来自 tmpfs 挂载。由于旧内核的挂载在新内核中不存在，文件的路径、owner、mode、扩展属性等元数据均不保留。</p><blockquote><p><strong>学习价值</strong>：展示了 LUO 文件恢复接口如何通过用户态创建的目标文件绕过挂载点不可恢复的问题，是理解 tmpfs Live Update 设计的好例子。</p></blockquote><h3 id="c9578a7405e1-·-patch-v4-11-19-mm-shmem-luo-require-permission-to-preserve-a-file" tabindex="-1"><code>c9578a7405e1</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-12-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 11/19] mm/shmem_luo: Require permission to preserve a file</a> <a class="header-anchor" href="#c9578a7405e1-·-patch-v4-11-19-mm-shmem-luo-require-permission-to-preserve-a-file" aria-label="Permalink to &quot;`c9578a7405e1` · [[PATCH v4 11/19] mm/shmem_luo: Require permission to preserve a file](https://lore.kernel.org/all/20261111002358.1842967-12-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁为文件保留增加权限要求：必须以读方式打开文件且调用者具有写权限，同时允许 owner 保留 immutable 文件或只读 superblock 上的文件，但拒绝 append-only 文件。文件被保留期间其大小对所有使用者冻结，truncate、fallocate() 和越界写入均返回 -EPERM。要求写权限可防止仅有只读 fd 的进程触发大小冻结。</p><blockquote><p><strong>学习价值</strong>：体现了 Live Update 安全语义与 VFS 权限模型（immutable、append-only、写权限）的交互，对理解内核安全设计很有参考价值。</p></blockquote><h3 id="e4c842fc0ea3-·-patch-v4-10-19-mm-shmem-luo-don-t-make-early-retrieve-failures-permanent" tabindex="-1"><code>e4c842fc0ea3</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-11-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 10/19] mm/shmem_luo: Don&#39;t make early retrieve failures permanent</a> <a class="header-anchor" href="#e4c842fc0ea3-·-patch-v4-10-19-mm-shmem-luo-don-t-make-early-retrieve-failures-permanent" aria-label="Permalink to &quot;`e4c842fc0ea3` · [[PATCH v4 10/19] mm/shmem_luo: Don&#39;t make early retrieve failures permanent](https://lore.kernel.org/all/20261111002358.1842967-11-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁将 shmem_luo_retrieve() 在开始恢复 folios 之前的失败标记为可重试：若没有任何 retrieve 成功，finish() 会像处理从未被恢复的文件一样释放保留状态。在 folios 恢复之前保留状态未被消费，可留给后续可能成功的 retrieve（如 memfd_alloc_file() 因 -ENOMEM 失败的情形）。例外是本内核无法恢复的文件（如包含不支持的 seals），重试无意义，保持永久失败。</p><blockquote><p><strong>学习价值</strong>：展示了内核错误处理中可重试与永久失败的区分，以及状态机设计如何避免误释放资源。</p></blockquote><h3 id="_8f93db81837e-·-patch-v4-09-19-mm-shmem-luo-leave-freeing-the-preserved-state-to-finish" tabindex="-1"><code>8f93db81837e</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-10-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 09/19] mm/shmem_luo: Leave freeing the preserved state to finish()</a> <a class="header-anchor" href="#_8f93db81837e-·-patch-v4-09-19-mm-shmem-luo-leave-freeing-the-preserved-state-to-finish" aria-label="Permalink to &quot;`8f93db81837e` · [[PATCH v4 09/19] mm/shmem_luo: Leave freeing the preserved state to finish()](https://lore.kernel.org/all/20261111002358.1842967-10-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁重构资源管理：shmem_luo_retrieve() 不再释放序列化状态，改由 finish() 统一释放每个文件剩余的保留状态；retrieve() 恢复 folios 后将序列化状态中的 nr_folios 置 0，使 finish() 只释放其余部分。这修复了 retrieve 在恢复 folios 前失败（如文件含不支持的 seals 或 memfd_alloc_file() 失败）时泄漏保留 folios 的问题。</p><blockquote><p><strong>学习价值</strong>：是学习内核资源所有权转移与错误路径清理的典型案例，体现了“谁分配谁释放”原则的灵活应用。</p></blockquote><h3 id="_46f91c2e823c-·-patch-v4-08-19-liveupdate-let-file-handlers-retrieve-into-an-existing-file" tabindex="-1"><code>46f91c2e823c</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-9-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 08/19] liveupdate: Let file handlers retrieve into an existing file</a> <a class="header-anchor" href="#_46f91c2e823c-·-patch-v4-08-19-liveupdate-let-file-handlers-retrieve-into-an-existing-file" aria-label="Permalink to &quot;`46f91c2e823c` · [[PATCH v4 08/19] liveupdate: Let file handlers retrieve into an existing file](https://lore.kernel.org/all/20261111002358.1842967-9-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁为 LUO 增加 liveupdate_claim_file() 和 liveupdate_unclaim_file()，供文件 handler 的 .retrieve() 回调在恢复保留状态前让 LUO 接管一个已存在的文件，并允许回调返回该文件的 fd，使 LIVEUPDATE_SESSION_RETRIEVE_FD 返回它而非新建的 fd。LUO 在 .retrieve() 返回后开始管理该文件，若文件已被管理则使 retrieve 失败。这为 shmem handler 将 tmpfs 文件恢复到已存在文件铺路。</p><blockquote><p><strong>学习价值</strong>：展示了 Live Update 框架中 handler 回调接口的演进设计，对理解内核子系统间 API 扩展方式很有帮助。</p></blockquote><h3 id="_63301c062117-·-patch-v4-07-19-liveupdate-add-helpers-to-track-the-files-that-luo-manages" tabindex="-1"><code>63301c062117</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-8-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 07/19] liveupdate: Add helpers to track the files that LUO manages</a> <a class="header-anchor" href="#_63301c062117-·-patch-v4-07-19-liveupdate-add-helpers-to-track-the-files-that-luo-manages" aria-label="Permalink to &quot;`63301c062117` · [[PATCH v4 07/19] liveupdate: Add helpers to track the files that LUO manages](https://lore.kernel.org/all/20261111002358.1842967-8-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁新增 luo_track_file() 和 luo_untrack_file() 辅助函数，用于向 luo_preserved_files 添加和移除文件，替代原来对 xa_insert()/xa_erase() 与 luo_get_id() 的手工编码。辅助函数将 key 生成和 -EBUSY 处理集中在一处，为后续让文件 handler 使 LUO 跟踪其恢复目标文件做准备。无功能性变化。</p><blockquote><p><strong>学习价值</strong>：典型的内核代码重构补丁，展示了如何通过封装消除重复代码、为多使用者扩展接口。</p></blockquote><h3 id="_2a303066a0e0-·-patch-v4-06-19-liveupdate-don-t-warn-if-tracking-a-retrieved-file-fails" tabindex="-1"><code>2a303066a0e0</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-7-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 06/19] liveupdate: Don&#39;t WARN if tracking a retrieved file fails</a> <a class="header-anchor" href="#_2a303066a0e0-·-patch-v4-06-19-liveupdate-don-t-warn-if-tracking-a-retrieved-file-fails" aria-label="Permalink to &quot;`2a303066a0e0` · [[PATCH v4 06/19] liveupdate: Don&#39;t WARN if tracking a retrieved file fails](https://lore.kernel.org/all/20261111002358.1842967-7-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁将“向 luo_preserved_files 添加被恢复文件失败”从 WARN_ON() 改为正常错误处理：失败被标记为永久，文件保留到文件集 finish() 为止。仅当文件已被跟踪（-EBUSY，属于内核 bug）时才告警。xa_insert() 可能因 -ENOMEM 失败且可被用户态通过 LIVEUPDATE_SESSION_RETRIEVE_FD 触发，若告警则用户态可借 panic_on_warn 使系统崩溃。</p><blockquote><p><strong>学习价值</strong>：生动说明了为什么用户态可触发的错误路径不应使用 WARN_ON，是内核防御性编程的重要教训。</p></blockquote><h3 id="f009e55c0563-·-patch-v4-05-19-mm-rename-memfd-luo-to-shmem-luo" tabindex="-1"><code>f009e55c0563</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-6-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 05/19] mm: Rename memfd_luo to shmem_luo</a> <a class="header-anchor" href="#f009e55c0563-·-patch-v4-05-19-mm-rename-memfd-luo-to-shmem-luo" aria-label="Permalink to &quot;`f009e55c0563` · [[PATCH v4 05/19] mm: Rename memfd_luo to shmem_luo](https://lore.kernel.org/all/20261111002358.1842967-6-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁将 memfd Live Update 文件 handler 从 memfd_luo 重命名为 shmem_luo，包括源文件、KHO ABI 头文件、文档和 Kconfig 选项（CONFIG_LIVEUPDATE_MEMFD 改为 CONFIG_LIVEUPDATE_SHMEM）。原因是该 handler 保留的是 shmem 文件，后续补丁将其扩展到 tmpfs 挂载上的其他文件，memfd 名称会产生误导；而 MFD_HUGETLB 创建的 memfd 属于 hugetlbfs，需要单独的 handler。handler 的 compatible 字符串 &quot;memfd-v2&quot; 保持不变。</p><blockquote><p><strong>学习价值</strong>：展示了内核命名如何随功能范围扩展而演进，以及 ABI 兼容字符串与代码命名的解耦处理。</p></blockquote><h3 id="_63abfa79a677-·-patch-v4-03-19-selftests-liveupdate-add-tests-for-preserve-and-retrieve-user-argument" tabindex="-1"><code>63abfa79a677</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-4-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 03/19] selftests/liveupdate: Add tests for preserve and retrieve user argument</a> <a class="header-anchor" href="#_63abfa79a677-·-patch-v4-03-19-selftests-liveupdate-add-tests-for-preserve-and-retrieve-user-argument" aria-label="Permalink to &quot;`63abfa79a677` · [[PATCH v4 03/19] selftests/liveupdate: Add tests for preserve and retrieve user argument](https://lore.kernel.org/all/20261111002358.1842967-4-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁为 selftests/liveupdate 新增测试，验证 LIVEUPDATE_SESSION_PRESERVE_FD 和 LIVEUPDATE_SESSION_RETRIEVE_FD 的用户参数支持。在 libliveupdate 中新增 luo_session_preserve_fd_arg() 和 luo_session_retrieve_fd_arg() 辅助函数，并添加 preserve_memfd_with_arg 测试用例，验证 memfd 保留对非零参数返回 -EOPNOTSUPP、接受显式零参数，并与仅传递到 token 字段的旧 struct 大小保持兼容。</p><blockquote><p><strong>学习价值</strong>：展示了内核自测试如何验证新 uapi 参数的向后兼容性，是学习 kselftest 与 uapi 演进结合的好材料。</p></blockquote><h3 id="d26cd13fc46f-·-patch-v4-04-19-liveupdate-allow-file-handlers-to-mark-retrieve-failures-as-retryable" tabindex="-1"><code>d26cd13fc46f</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-5-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 04/19] liveupdate: Allow file handlers to mark retrieve failures as retryable</a> <a class="header-anchor" href="#d26cd13fc46f-·-patch-v4-04-19-liveupdate-allow-file-handlers-to-mark-retrieve-failures-as-retryable" aria-label="Permalink to &quot;`d26cd13fc46f` · [[PATCH v4 04/19] liveupdate: Allow file handlers to mark retrieve failures as retryable](https://lore.kernel.org/all/20261111002358.1842967-5-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>liveupdate (LUO) 子系统新增 retryable 输出标志，允许文件 handler 的 .retrieve() 回调在出错时声明自己尚未消费保留状态，从而让用户态可以重试 retrieve 操作。若文件最终未被 retrieve，.finish() 仍会释放保留状态。此前 luo_retrieve_file() 一旦记录 retrieve_status 错误就会永久阻止后续重试。</p><blockquote><p><strong>学习价值</strong>：展示了内核中回调接口的错误语义设计——区分&#39;已部分消费状态&#39;与&#39;可安全重试&#39;两种失败，是理解 liveupdate 状态迁移机制的好例子。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_3f21d5dffe13-·-patch-net-v5-net-ethernet-adi-adin1110-mask-the-rx-irq-of-the-port-being-stopped" tabindex="-1"><code>3f21d5dffe13</code> · <a href="https://lore.kernel.org/all/20261111-adin1110-net-stop-v5-1-yuehongwu@cmss.chinamobile.com/" target="_blank" rel="noreferrer">[PATCH net v5] net: ethernet: adi: adin1110: mask the RX IRQ of the port being stopped</a> <a class="header-anchor" href="#_3f21d5dffe13-·-patch-net-v5-net-ethernet-adi-adin1110-mask-the-rx-irq-of-the-port-being-stopped" aria-label="Permalink to &quot;`3f21d5dffe13` · [[PATCH net v5] net: ethernet: adi: adin1110: mask the RX IRQ of the port being stopped](https://lore.kernel.org/all/20261111-adin1110-net-stop-v5-1-yuehongwu@cmss.chinamobile.com/)&quot;">​</a></h3><p><em>Yuehong Wu (<a href="mailto:wuyuehong@cmss.chinamobile.com" target="_blank" rel="noreferrer">wuyuehong@cmss.chinamobile.com</a>)｜netdev</em></p><p>修复 adin1110/adin2111 以太网驱动中 adin1110_net_stop() 的 RX 中断掩码 bug：停止 port 0 时错误地掩蔽了 port 1 的 RX-ready 中断（反之亦然），与 adin1110_port_rx_ready() 的端口映射相反。结果是 ADIN2111 上对端口的 RX 会停滞，ADIN1110 上 RX 中断根本未被掩蔽，且由于电平触发中断导致问题持续。</p><blockquote><p><strong>学习价值</strong>：一个典型的多端口驱动中寄存器位映射错乱的 bug，提醒学习者在驱动开发中仔细核对每个端口对应的硬件位定义。</p></blockquote><h3 id="_748bc0c580dd-·-patch-net-next-v1-05-15-net-add-metadata-psp-dst-to-carry-a-psp-association-on-an-skb" tabindex="-1"><code>748bc0c580dd</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-6-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 05/15] net: add METADATA_PSP dst to carry a psp association on an skb</a> <a class="header-anchor" href="#_748bc0c580dd-·-patch-net-next-v1-05-15-net-add-metadata-psp-dst-to-carry-a-psp-association-on-an-skb" aria-label="Permalink to &quot;`748bc0c580dd` · [[PATCH net-next v1 05/15] net: add METADATA_PSP dst to carry a psp association on an skb](https://lore.kernel.org/all/20261111005533.6436-6-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>为 PSP (传输层加密协议) 引入 METADATA_PSP 类型的 metadata_dst，使 psp association 可以附加到没有 socket 的 skb 上（例如由 tc 规则创建）。psp_skb_get_assoc_rcu() 改为先检查 METADATA_PSP 再回退到 socket，使现有驱动 tx 路径（mlx5、netdevsim）无需修改即可加密此类报文，并确保报文在正确的设备上发送以避免明文上线。</p><blockquote><p><strong>学习价值</strong>：展示了 metadata_dst 机制如何将协议状态与 socket 解耦并传递到驱动层，是理解 skb 元数据传递和硬件加密卸载架构的优秀案例。</p></blockquote><h3 id="_5d4c0dc634d1-·-patch-net-next-v1-04-15-psp-add-support-for-socket-less-psp-associations" tabindex="-1"><code>5d4c0dc634d1</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-5-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 04/15] psp: add support for socket-less psp associations</a> <a class="header-anchor" href="#_5d4c0dc634d1-·-patch-net-next-v1-04-15-psp-add-support-for-socket-less-psp-associations" aria-label="Permalink to &quot;`5d4c0dc634d1` · [[PATCH net-next v1 04/15] psp: add support for socket-less psp associations](https://lore.kernel.org/all/20261111005533.6436-5-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>为 PSP 增加无 socket 绑定的 association 支持：新增一个小型注册表管理未绑定的 rx/tx association，通过 id 引用，供 tc 等其他协议栈部分附加到报文上。rx association 记录 spi、version 和设备密钥代数，tc flower 过滤器可通过 psp_spi、psp_ver、psp_dev 字段匹配而非按 id 引用。</p><blockquote><p><strong>学习价值</strong>：演示了如何将原本绑定在 socket 上的加密状态抽象为可独立引用的注册表对象，是协议状态管理设计的参考。</p></blockquote><h3 id="_999aa004dbf8-·-patch-net-next-v1-09-15-net-sched-add-act-psp-for-psp-transport-mode" tabindex="-1"><code>999aa004dbf8</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-10-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 09/15] net/sched: add act_psp for psp transport mode</a> <a class="header-anchor" href="#_999aa004dbf8-·-patch-net-next-v1-09-15-net-sched-add-act-psp-for-psp-transport-mode" aria-label="Permalink to &quot;`999aa004dbf8` · [[PATCH net-next v1 09/15] net/sched: add act_psp for psp transport mode](https://lore.kernel.org/all/20261111005533.6436-10-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>新增 tc action act_psp，用于 PSP transport 模式的封装与加密：encap 将 psp tx association 作为 METADATA_PSP dst 附加到 skb，报文必须在 association 对应 PSP 设备的主 netdev 上发送（egress encap 或 redirect），否则丢弃。ingress 上的 encap 仅支持硬件卸载，软件路径直接丢包以防止明文泄露。</p><blockquote><p><strong>学习价值</strong>：结合 tc action 与硬件加密卸载的实现细节，展示了内核如何在数据路径上强制安全不变量（绝不明文上线）。</p></blockquote><h3 id="_4ed12fed061c-·-patch-net-next-v1-14-15-selftests-tc-testing-add-tests-for-the-psp-action" tabindex="-1"><code>4ed12fed061c</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-15-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 14/15] selftests: tc-testing: add tests for the psp action</a> <a class="header-anchor" href="#_4ed12fed061c-·-patch-net-next-v1-14-15-selftests-tc-testing-add-tests-for-the-psp-action" aria-label="Permalink to &quot;`4ed12fed061c` · [[PATCH net-next v1 14/15] selftests: tc-testing: add tests for the psp action](https://lore.kernel.org/all/20261111005533.6436-15-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>为 tc psp action 添加 tc-testing 自测：覆盖 psp decap action 的添加/替换/删除/flush，验证无 association 的 encap、不存在的 association、带 association 的 decap 均被拒绝，以及 flower 过滤器对 psp_spi、psp_ver、psp_dev 的匹配和越界值拒绝。测试依赖支持 psp 的 tc 工具，缺失时自动跳过。</p><blockquote><p><strong>学习价值</strong>：提供了 tc action 自测的编写范式，包括 action 生命周期操作和 flower 匹配字段的边界测试方法。</p></blockquote><h3 id="_6a628fff4b88-·-patch-net-next-v1-11-15-selftests-drv-net-psp-test-socket-less-associations-and-the-tc-psp-action" tabindex="-1"><code>6a628fff4b88</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-12-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 11/15] selftests: drv-net: psp: test socket-less associations and the tc psp action</a> <a class="header-anchor" href="#_6a628fff4b88-·-patch-net-next-v1-11-15-selftests-drv-net-psp-test-socket-less-associations-and-the-tc-psp-action" aria-label="Permalink to &quot;`6a628fff4b88` · [[PATCH net-next v1 11/15] selftests: drv-net: psp: test socket-less associations and the tc psp action](https://lore.kernel.org/all/20261111005533.6436-12-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>在 drv-net psp.py 自测中覆盖无 socket association 命令和 tc psp action 的数据路径：本地普通 TCP socket 连接到对端 PSP socket，通过 tc 在 ingress 用 flower 匹配 psp_spi/psp_ver/psp_dev 并用 psp decap 移除状态，在 egress 用 psp encap 附加 Tx association 由设备加密。测试还覆盖 key rotation 导致的 stale association 场景。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 veth + tc + Python 自测框架端到端验证加密数据路径，是学习 netdev 自测体系的好材料。</p></blockquote><h3 id="_335c6cd9a693-·-patch-net-next-v1-15-15-documentation-networking-psp-document-socket-less-associations" tabindex="-1"><code>335c6cd9a693</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-16-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 15/15] Documentation: networking: psp: document socket-less associations</a> <a class="header-anchor" href="#_335c6cd9a693-·-patch-net-next-v1-15-15-documentation-networking-psp-document-socket-less-associations" aria-label="Permalink to &quot;`335c6cd9a693` · [[PATCH net-next v1 15/15] Documentation: networking: psp: document socket-less associations](https://lore.kernel.org/all/20261111005533.6436-16-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>更新 Documentation/networking/psp.rst，描述 socket 与 tc 两种场景下 PSP association 的差异，记录管理无 socket association 的新 netlink 命令、psp tc action 及 flower 的 psp_spi/psp_ver/psp_dev 匹配，并新增 PSP 设备统计信息章节。</p><blockquote><p><strong>学习价值</strong>：内核文档与代码同步演进的范例，读者可通过 psp.rst 快速理解 PSP 加密框架的整体设计。</p></blockquote><h3 id="_69132bd36df4-·-patch-net-next-v1-12-15-selftests-drv-net-psp-test-that-software-encap-on-ingress-drops" tabindex="-1"><code>69132bd36df4</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-13-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 12/15] selftests: drv-net: psp: test that software encap on ingress drops</a> <a class="header-anchor" href="#_69132bd36df4-·-patch-net-next-v1-12-15-selftests-drv-net-psp-test-that-software-encap-on-ingress-drops" aria-label="Permalink to &quot;`69132bd36df4` · [[PATCH net-next v1 12/15] selftests: drv-net: psp: test that software encap on ingress drops](https://lore.kernel.org/all/20261111005533.6436-13-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>在 drv-net psp.py 中新增测试验证软件路径下 ingress 上的 psp encap 会丢包（ingress encap 仅支持硬件卸载）：通过 veth 后的客户端流量测试，验证转发报文不会以明文到达远端，发往本地地址的报文也不会到达本地 socket，IPv4 和 IPv6 均覆盖。</p><blockquote><p><strong>学习价值</strong>：体现了内核安全功能测试的核心思路——不仅验证正常路径，更要验证失败路径不会泄露明文数据。</p></blockquote><h3 id="_0898e8dc3820-·-patch-net-next-v1-08-15-psp-only-give-time-wait-sockets-of-psp-connections-a-validator" tabindex="-1"><code>0898e8dc3820</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-9-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 08/15] psp: only give time-wait sockets of psp connections a validator</a> <a class="header-anchor" href="#_0898e8dc3820-·-patch-net-next-v1-08-15-psp-only-give-time-wait-sockets-of-psp-connections-a-validator" aria-label="Permalink to &quot;`0898e8dc3820` · [[PATCH net-next v1 08/15] psp: only give time-wait sockets of psp connections a validator](https://lore.kernel.org/all/20261111005533.6436-9-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>修正 psp_twsk_init() 的行为：此前无论 TCP time-wait socket 是否有 PSP 卸载都会设置 tw_validate_xmit_skb 验证器。由于验证器会让 socket 看起来拥有自己的加密卸载，而 tc psp action 依赖此语义（encap 会拒绝此类 socket 的报文，sk_validate_xmit_skb() 会丢弃其带 psp association 的报文），现在仅在 socket 确有 psp association 时才设置验证器。</p><blockquote><p><strong>学习价值</strong>：展示了 TCP time-wait socket 的 xmit 验证器机制，以及看似无害的冗余设置如何与后续新特性产生语义冲突。</p></blockquote><h3 id="_11582c987098-·-patch-net-next-v1-13-15-selftests-tc-testing-run-dependson-probes-outside-the-test-namespace" tabindex="-1"><code>11582c987098</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-14-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 13/15] selftests: tc-testing: run dependsOn probes outside the test namespace</a> <a class="header-anchor" href="#_11582c987098-·-patch-net-next-v1-13-15-selftests-tc-testing-run-dependson-probes-outside-the-test-namespace" aria-label="Permalink to &quot;`11582c987098` · [[PATCH net-next v1 13/15] selftests: tc-testing: run dependsOn probes outside the test namespace](https://lore.kernel.org/all/20261111005533.6436-14-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>tc-testing 自测框架中，dependsOn 探针命令会被 nsPlugin 加上 &quot;ip netns exec tcut&quot; 前缀，但探针在测试 namespace 创建之前执行，导致所有需要 nsPlugin 的探针测试被跳过（如 mirred blockid 和 tunnel_key nofrag 测试）。本补丁将探针改为独立的 &quot;probe&quot; 阶段，使其在基础 namespace 中运行，因为探针本意是检查 tc 和内核能力而非测试 namespace 内的东西。</p><blockquote><p><strong>学习价值</strong>：展示了 tc-testing 框架的执行阶段机制和 namespace 隔离设计，对理解网络自测框架的测试生命周期很有帮助。</p></blockquote><h3 id="_63e6d778407f-·-patch-net-next-v1-03-15-psp-declare-psp-assoc-set-tx-in-psp-h" tabindex="-1"><code>63e6d778407f</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-4-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 03/15] psp: declare psp_assoc_set_tx() in psp.h</a> <a class="header-anchor" href="#_63e6d778407f-·-patch-net-next-v1-03-15-psp-declare-psp-assoc-set-tx-in-psp-h" aria-label="Permalink to &quot;`63e6d778407f` · [[PATCH net-next v1 03/15] psp: declare psp_assoc_set_tx() in psp.h](https://lore.kernel.org/all/20261111005533.6436-4-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>为支持后续引入的 socket-less PSP 关联（需要与 socket 同样的方式安装 tx key），本补丁将 psp_assoc_set_tx() 从 static 改为非 static，并在 net/psp/psp.h 中添加声明。这是 PSP socket-less 关联系列的基础重构步骤。</p><blockquote><p><strong>学习价值</strong>：展示了内核代码演进中典型的接口导出重构模式，可学习内核头文件声明与函数可见性管理的惯例。</p></blockquote><h3 id="e1bb1164e91b-·-patch-net-next-v1-02-15-psp-take-the-psp-nexthdr-from-the-packet-on-encap" tabindex="-1"><code>e1bb1164e91b</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-3-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 02/15] psp: take the psp nexthdr from the packet on encap</a> <a class="header-anchor" href="#e1bb1164e91b-·-patch-net-next-v1-02-15-psp-take-the-psp-nexthdr-from-the-packet-on-encap" aria-label="Permalink to &quot;`e1bb1164e91b` · [[PATCH net-next v1 02/15] psp: take the psp nexthdr from the packet on encap](https://lore.kernel.org/all/20261111005533.6436-3-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>PSP socket 支持此前仅限 TCP，psp_dev_encapsulate() 硬编码 IPPROTO_TCP 作为 PSP nexthdr。本补丁改为从原始报文的 IP 头中提取 nexthdr，为 socket-less 关联支持 UDP 流量做准备。同时明确了不支持的场景：IPv6 扩展头存在（传输头不在固定 IP 头之后）以及 IPv4 分片报文。</p><blockquote><p><strong>学习价值</strong>：通过 PSP 封装逻辑展示了如何从 skb 的 IP 头正确解析传输层协议，以及内核对分片和扩展头报文的处理边界。</p></blockquote><h3 id="b3ce059fd15c-·-patch-net-next-v1-07-15-bpf-don-t-redirect-decrypted-skbs-from-egress-to-ingress" tabindex="-1"><code>b3ce059fd15c</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-8-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 07/15] bpf: don&#39;t redirect decrypted skbs from egress to ingress</a> <a class="header-anchor" href="#b3ce059fd15c-·-patch-net-next-v1-07-15-bpf-don-t-redirect-decrypted-skbs-from-egress-to-ingress" aria-label="Permalink to &quot;`b3ce059fd15c` · [[PATCH net-next v1 07/15] bpf: don&#39;t redirect decrypted skbs from egress to ingress](https://lore.kernel.org/all/20261111005533.6436-8-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>skb-&gt;decrypted 标志在发送路径表示设备需要加密报文（如 ktls/PSP offload socket），在接收路径则表示设备已解密。bpf_redirect() 和 bpf_clone_redirect() 使用 BPF_F_INGRESS 时会将该标志带入接收路径，造成语义错误。本补丁阻止已标记 decrypted 的 skb 从 egress 重定向到 ingress，避免标志被误读。</p><blockquote><p><strong>学习价值</strong>：深入讲解 skb-&gt;decrypted 标志的双向语义，是理解内核 offload 路径与 BPF redirect 交互的绝佳案例。</p></blockquote><h3 id="cb5744c41720-·-patch-net-next-v1-06-15-net-sched-act-mirred-don-t-send-decrypted-skbs-from-egress-to-ingress" tabindex="-1"><code>cb5744c41720</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-7-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 06/15] net/sched: act_mirred: don&#39;t send decrypted skbs from egress to ingress</a> <a class="header-anchor" href="#cb5744c41720-·-patch-net-next-v1-06-15-net-sched-act-mirred-don-t-send-decrypted-skbs-from-egress-to-ingress" aria-label="Permalink to &quot;`cb5744c41720` · [[PATCH net-next v1 06/15] net/sched: act_mirred: don&#39;t send decrypted skbs from egress to ingress](https://lore.kernel.org/all/20261111005533.6436-7-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>与 BPF redirect 补丁同理，act_mirred 在 redirect/mirror 报文从 egress 到 ingress 时，skb-&gt;decrypted 标志会被错误地解读为设备已解密。本补丁让 act_mirred 不再将带 decrypted 标志的 skb 发送到 ingress 路径，因为该报文不会经过本应加密它的设备。</p><blockquote><p><strong>学习价值</strong>：结合 tc mirred action 展示了同一 decrypted 语义问题在另一个子系统中的修复，有助于理解 tc action 与 offload 标志的交互。</p></blockquote><h3 id="c65c5c8456c6-·-patch-net-next-v1-10-15-net-sched-flower-add-psp-spi-psp-ver-and-psp-dev-matches" tabindex="-1"><code>c65c5c8456c6</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-11-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 10/15] net/sched: flower: add psp_spi, psp_ver, and psp_dev matches</a> <a class="header-anchor" href="#c65c5c8456c6-·-patch-net-next-v1-10-15-net-sched-flower-add-psp-spi-psp-ver-and-psp-dev-matches" aria-label="Permalink to &quot;`c65c5c8456c6` · [[PATCH net-next v1 10/15] net/sched: flower: add psp_spi, psp_ver, and psp_dev matches](https://lore.kernel.org/all/20261111005533.6436-11-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>本补丁在 flow dissector 中新增从 PSP Rx 状态（SKB_EXT_PSP）填充的 key，并为 flower 分类器添加 psp_spi（带掩码）、psp_ver 和 psp_dev 三个匹配项，分别对应解密所用的 SPI、PSP 版本和解密设备 ID。三者组合可将 tc 规则绑定到特定 Rx 关联，例如配合 &quot;action psp decap&quot; 去除 PSP 状态以便转发。</p><blockquote><p><strong>学习价值</strong>：展示了 flow dissector key 扩展和 flower 匹配项的完整添加流程，是学习 tc 分类器扩展开发的优秀参考。</p></blockquote><h3 id="cc7a8b798751-·-patch-net-next-v1-01-15-psp-get-netns-from-net-device-instead-of-sock" tabindex="-1"><code>cc7a8b798751</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-2-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 01/15] psp: get netns from net_device instead of sock</a> <a class="header-anchor" href="#cc7a8b798751-·-patch-net-next-v1-01-15-psp-get-netns-from-net-device-instead-of-sock" aria-label="Permalink to &quot;`cc7a8b798751` · [[PATCH net-next v1 01/15] psp: get netns from net_device instead of sock](https://lore.kernel.org/all/20261111005533.6436-2-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>目前每个 PSP skb 都关联到 socket，但后续 tc flower 规则等途径也能将 PSP 关联附加到 skb 上。本补丁改为从发送设备（net_device）获取 netns，psp_write_headers() 在 socket 场景下显式使用 sock_net(sk) 以保持现有行为。涉及 mlx5 psp_rxtx.c、netdevsim 和 psp_main.c 三处修改。</p><blockquote><p><strong>学习价值</strong>：展示了为支持新功能而进行的依赖解耦重构，可学习内核中从 sock 迁移到 net_device 获取 netns 的典型做法。</p></blockquote><h3 id="_7bf47f7e673a-·-patch-net-next-v1-00-15-psp-introduce-socket-less-associations-1" tabindex="-1"><code>7bf47f7e673a</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-1-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 00/15] psp: introduce socket-less associations</a> <a class="header-anchor" href="#_7bf47f7e673a-·-patch-net-next-v1-00-15-psp-introduce-socket-less-associations-1" aria-label="Permalink to &quot;`7bf47f7e673a` · [[PATCH net-next v1 00/15] psp: introduce socket-less associations](https://lore.kernel.org/all/20261111005533.6436-1-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>本系列（共 15 个补丁）引入 socket-less PSP 关联，使 PSP 封装和加密可应用于转发流量，实现透明的 PSP 隧道。socket-less 关联的生命周期通过 PSP netlink family 管理，存储在小型注册表中并可通过 ID 寻址。需要用户态配合管理 tc 规则和编排密钥交换。系列还包括 tc psp action、flower 匹配、decrypted skb 处理等配套改动。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，完整阐述了 PSP 传输模式加密架构从 socket 绑定到通用化的设计演进，是理解 PSP 子系统全貌的最佳入口。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_40d62b00c0b8-·-patch-v2-3-3-kconfig-show-continuation-at-the-end-of-wrapped-lines" tabindex="-1"><code>40d62b00c0b8</code> · <a href="https://lore.kernel.org/all/20261110173526.1548434-4-julianbraha@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 3/3] kconfig: show continuation at the end of wrapped lines</a> <a class="header-anchor" href="#_40d62b00c0b8-·-patch-v2-3-3-kconfig-show-continuation-at-the-end-of-wrapped-lines" aria-label="Permalink to &quot;`40d62b00c0b8` · [[PATCH v2 3/3] kconfig: show continuation at the end of wrapped lines](https://lore.kernel.org/all/20261110173526.1548434-4-julianbraha@gmail.com/)&quot;">​</a></h3><p><em>Julian Braha (<a href="mailto:julianbraha@gmail.com" target="_blank" rel="noreferrer">julianbraha@gmail.com</a>)｜rust-for-linux</em></p><p>本补丁在 menuconfig 中换行显示的表达式末尾添加可见的续行符 &#39;&#39;，因为某些换行不明显（例如行尾是符号名而非操作符时）。例如 &quot;Depends on: GPIOLIB [=y] &amp;&amp; (MFD_TQMX86 [=y] || COMPILE_TEST [=y]) \\ &amp;&amp; HAS_IOPORT_MAP [=y]&quot;，修改位于 scripts/kconfig/expr.c。</p><blockquote><p><strong>学习价值</strong>：虽发到 rust-for-linux 列表，实为 kconfig 工具的用户体验改进，展示了内核构建系统小而实用的补丁形态。</p></blockquote><h3 id="_4828f2a9050e-·-patch-v2-2-3-kconfig-wrap-long-expressions-in-menuconfig" tabindex="-1"><code>4828f2a9050e</code> · <a href="https://lore.kernel.org/all/20261110173526.1548434-3-julianbraha@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 2/3] kconfig: wrap long expressions in menuconfig</a> <a class="header-anchor" href="#_4828f2a9050e-·-patch-v2-2-3-kconfig-wrap-long-expressions-in-menuconfig" aria-label="Permalink to &quot;`4828f2a9050e` · [[PATCH v2 2/3] kconfig: wrap long expressions in menuconfig](https://lore.kernel.org/all/20261110173526.1548434-3-julianbraha@gmail.com/)&quot;">​</a></h3><p><em>Julian Braha (<a href="mailto:julianbraha@gmail.com" target="_blank" rel="noreferrer">julianbraha@gmail.com</a>)｜rust-for-linux</em></p><p>menuconfig 搜索结果中的长表达式（如 &#39;Depends on&#39;、&#39;Selected by&#39;、&#39;Range&#39;）需要水平滚动查看，非常耗时。本补丁使其在窗口末尾按 token 换行并保持相同缩进，同时确保 &#39;!&#39; 取反符号与左侧符号保持连接、值标注与右侧保持连接。&#39;help&#39; 文本框使用同一表达式打印器，因此也间接受益。</p><blockquote><p><strong>学习价值</strong>：展示了 kconfig 表达式打印器的换行实现细节，对理解 menuconfig 工具内部实现和内核构建系统有帮助。</p></blockquote><h3 id="_719aef1a3818-·-patch-v2-1-3-kconfig-print-the-output-of-expr-alloc-and-instead-of-printing" tabindex="-1"><code>719aef1a3818</code> · <a href="https://lore.kernel.org/all/20261110173526.1548434-2-julianbraha@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 1/3] kconfig: print the output of expr_alloc_and() instead of printing &#39;&amp;&amp;&#39;</a> <a class="header-anchor" href="#_719aef1a3818-·-patch-v2-1-3-kconfig-print-the-output-of-expr-alloc-and-instead-of-printing" aria-label="Permalink to &quot;`719aef1a3818` · [[PATCH v2 1/3] kconfig: print the output of expr_alloc_and() instead of printing &#39;&amp;&amp;&#39;](https://lore.kernel.org/all/20261110173526.1548434-2-julianbraha@gmail.com/)&quot;">​</a></h3><p><em>Julian Braha (<a href="mailto:julianbraha@gmail.com" target="_blank" rel="noreferrer">julianbraha@gmail.com</a>)｜rust-for-linux</em></p><p>该补丁清理 kconfig 中 &#39;select&#39; 和 &#39;imply&#39; 表达式的打印逻辑，改为调用 expr_alloc_and() 生成表达式并打印其输出，而不是直接打印字面量 &#39; &amp;&amp; &#39;。这是为了让行尾的 &#39;&amp;&amp;&#39; 能够正确换行，属于 menuconfig 表达式换行系列的一部分。</p><blockquote><p><strong>学习价值</strong>：通过阅读 scripts/kconfig/menu.c 的改动，可以学习内核构建系统 kconfig 内部表达式数据结构的处理方式，是理解 kconfig 实现细节的好材料。</p></blockquote><h3 id="_8f20ce11e672-·-patch-v2-0-3-kconfig-wrap-long-expressions-in-menuconfig" tabindex="-1"><code>8f20ce11e672</code> · <a href="https://lore.kernel.org/all/20261110173526.1548434-1-julianbraha@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 0/3] kconfig: wrap long expressions in menuconfig</a> <a class="header-anchor" href="#_8f20ce11e672-·-patch-v2-0-3-kconfig-wrap-long-expressions-in-menuconfig" aria-label="Permalink to &quot;`8f20ce11e672` · [[PATCH v2 0/3] kconfig: wrap long expressions in menuconfig](https://lore.kernel.org/all/20261110173526.1548434-1-julianbraha@gmail.com/)&quot;">​</a></h3><p><em>Julian Braha (<a href="mailto:julianbraha@gmail.com" target="_blank" rel="noreferrer">julianbraha@gmail.com</a>)｜rust-for-linux</em></p><p>该系列补丁解决 menuconfig 中长表达式（如 &#39;Depends on&#39;、&#39;Selected by&#39;、&#39;Range&#39; 部分）无法换行、需要横向滚动阅读的问题，起因是 Miguel Ojeda 反馈查看 RUST 依赖时横向滚动拖慢了调试。补丁在 token 边界处换行并保持缩进对齐，确保 &#39;!&#39; 取反符号与左侧选项符号保持连接，值标注与右侧符号保持连接，并在换行行尾添加 &#39;&#39; 提示续行。</p><blockquote><p><strong>学习价值</strong>：展示了内核开发者如何从实际调试痛点出发改进工具体验，学习者可借此了解 menuconfig 前端实现及补丁系列的组织方式。</p></blockquote><h3 id="_724dd63d79ce-·-patch-v2-09-28-drm-panthor-add-mali-v15-hardware-support" tabindex="-1"><code>724dd63d79ce</code> · <a href="https://lore.kernel.org/all/20261110153907.3241978-10-karunika.choo@arm.com/" target="_blank" rel="noreferrer">[PATCH v2 09/28] drm/panthor: Add Mali v15 hardware support</a> <a class="header-anchor" href="#_724dd63d79ce-·-patch-v2-09-28-drm-panthor-add-mali-v15-hardware-support" aria-label="Permalink to &quot;`724dd63d79ce` · [[PATCH v2 09/28] drm/panthor: Add Mali v15 hardware support](https://lore.kernel.org/all/20261110153907.3241978-10-karunika.choo@arm.com/)&quot;">​</a></h3><p><em>Karunika Choo (<a href="mailto:karunika.choo@arm.com" target="_blank" rel="noreferrer">karunika.choo@arm.com</a>)｜rust-for-linux</em></p><p>该补丁为 drm/panthor 驱动添加 Mali v15 GPU 的硬件描述，包括 v15 寄存器映射和产品识别信息，并将其接入设备匹配逻辑。同时添加 v15 GPU 的 compatibility string 并将 drm minor 版本提升到 10。</p><blockquote><p><strong>学习价值</strong>：适合学习 DRM 子系统中新硬件支持是如何通过寄存器定义、设备匹配和 uAPI 暴露来接入驱动的完整流程。</p></blockquote><h3 id="_79fd07b2a341-·-patch-v2-05-28-drm-panthor-add-64-bit-gpu-id-decoding-for-v15-gpus" tabindex="-1"><code>79fd07b2a341</code> · <a href="https://lore.kernel.org/all/20261110153907.3241978-6-karunika.choo@arm.com/" target="_blank" rel="noreferrer">[PATCH v2 05/28] drm/panthor: Add 64-bit GPU_ID decoding for v15 GPUs</a> <a class="header-anchor" href="#_79fd07b2a341-·-patch-v2-05-28-drm-panthor-add-64-bit-gpu-id-decoding-for-v15-gpus" aria-label="Permalink to &quot;`79fd07b2a341` · [[PATCH v2 05/28] drm/panthor: Add 64-bit GPU_ID decoding for v15 GPUs](https://lore.kernel.org/all/20261110153907.3241978-6-karunika.choo@arm.com/)&quot;">​</a></h3><p><em>Karunika Choo (<a href="mailto:karunika.choo@arm.com" target="_blank" rel="noreferrer">karunika.choo@arm.com</a>)｜rust-for-linux</em></p><p>Mali v15 GPU 暴露一个 64 位的 GPU_ID 寄存器，其字段布局与早期 GPU 不同。该补丁为新格式添加寄存器定义和解码辅助函数，在 compatibility 值表明是 v15 GPU 时读取 GPU_ID_WIDE，并填充缓存的 GPU_ID 字段和 uAPI 的 gpu_id_wide 字段，使 userspace 和驱动能正确识别 v15 GPU。</p><blockquote><p><strong>学习价值</strong>：展示了驱动如何处理硬件版本间的寄存器格式差异，是学习 GPU 驱动 uAPI 设计与硬件 ID 解码的实用案例。</p></blockquote><h3 id="ee14ec832905-·-patch-gpu-nova-core-use-pin-init-self-referential-support" tabindex="-1"><code>ee14ec832905</code> · <a href="https://lore.kernel.org/all/20261110152746.140351-1-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH] gpu: nova-core: use pin-init self-referential support</a> <a class="header-anchor" href="#ee14ec832905-·-patch-gpu-nova-core-use-pin-init-self-referential-support" aria-label="Permalink to &quot;`ee14ec832905` · [[PATCH] gpu: nova-core: use pin-init self-referential support](https://lore.kernel.org/all/20261110152746.140351-1-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>该补丁将 nova-core（NVIDIA GPU 的 Rust 驱动）中所有自引用借用改用 pin-init 的 self-referential 支持来表达，替换原先不安全的派生引用。改动涉及 driver.rs、gpu.rs、irq/gsp.rs 等多个文件，净减少约 8 行代码。</p><blockquote><p><strong>学习价值</strong>：是理解 Rust in Linux 中 pin-init API 如何安全处理自引用结构体的优秀实例，对学习 Rust 内核驱动的 unsafe 消除很有价值。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="_55c3caf359a4-·-amd-epyc-9996-benchmarks-show-unparalleled-performance-with-256-zen-6c-cores" tabindex="-1"><code>55c3caf359a4</code> · <a href="https://www.phoronix.com/review/amd-epyc-9996" target="_blank" rel="noreferrer">AMD EPYC 9996 Benchmarks Show Unparalleled Performance With 256 Zen 6C Cores</a> <a class="header-anchor" href="#_55c3caf359a4-·-amd-epyc-9996-benchmarks-show-unparalleled-performance-with-256-zen-6c-cores" aria-label="Permalink to &quot;`55c3caf359a4` · [AMD EPYC 9996 Benchmarks Show Unparalleled Performance With 256 Zen 6C Cores](https://www.phoronix.com/review/amd-epyc-9996)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD EPYC 9006 &quot;Venice&quot; 系列 SP7 处理器正式上市，旗舰 EPYC 9996 拥有 256 个 Zen 6C 核心，双路配置可达 512 核 / 1024 线程。Phoronix 的基准测试显示其性能表现极为出色。</p><blockquote><p><strong>学习价值</strong>：属于硬件评测新闻，但可作为观察大规模多核硬件对 Linux 内核可扩展性挑战的背景材料。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_7ac3686186a6-·-7-3-4-stable" tabindex="-1"><code>7ac3686186a6</code> · <a href="https://www.kernel.org/#kernel.org-stable-7.3.4-2026-11-10" target="_blank" rel="noreferrer">7.3.4: stable</a> <a class="header-anchor" href="#_7ac3686186a6-·-7-3-4-stable" aria-label="Permalink to &quot;`7ac3686186a6` · [7.3.4: stable](https://www.kernel.org/#kernel.org-stable-7.3.4-2026-11-10)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 Linux 7.3.4 stable 版本，发布日期为 2026-11-10，提供源码 tarball、PGP 签名、完整及增量 patch 和 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：stable 版本发布信息，学习者可关注其 ChangeLog 了解近期主线修复内容。</p></blockquote><h3 id="_66ce4af15bdf-·-6-18-63-longterm" tabindex="-1"><code>66ce4af15bdf</code> · <a href="https://www.kernel.org/#kernel.org-longterm-6.18.63-2026-11-10" target="_blank" rel="noreferrer">6.18.63: longterm</a> <a class="header-anchor" href="#_66ce4af15bdf-·-6-18-63-longterm" aria-label="Permalink to &quot;`66ce4af15bdf` · [6.18.63: longterm](https://www.kernel.org/#kernel.org-longterm-6.18.63-2026-11-10)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 Linux 6.18.63 longterm 版本，发布日期为 2026-11-10，提供源码 tarball、PGP 签名、完整及增量 patch 和 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：longterm 维护版本发布信息，适合了解长期支持内核的持续维护节奏。</p></blockquote><h3 id="_360e156d2a72-·-6-12-117-longterm" tabindex="-1"><code>360e156d2a72</code> · <a href="https://www.kernel.org/#kernel.org-longterm-6.12.117-2026-11-10" target="_blank" rel="noreferrer">6.12.117: longterm</a> <a class="header-anchor" href="#_360e156d2a72-·-6-12-117-longterm" aria-label="Permalink to &quot;`360e156d2a72` · [6.12.117: longterm](https://www.kernel.org/#kernel.org-longterm-6.12.117-2026-11-10)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 Linux 6.12.117 longterm 版本，发布日期为 2026-11-10，提供源码 tarball、PGP 签名、完整及增量 patch 和 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：longterm 维护版本发布信息，可通过 ChangeLog 跟踪 6.12 系列的 backport 修复情况。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="e4c67eb4406c-·-three-new-stable-kernels-for-tuesday" tabindex="-1"><code>e4c67eb4406c</code> · <a href="https://lwn.net/Articles/1106569/" target="_blank" rel="noreferrer">Three new stable kernels for Tuesday</a> <a class="header-anchor" href="#e4c67eb4406c-·-three-new-stable-kernels-for-tuesday" aria-label="Permalink to &quot;`e4c67eb4406c` · [Three new stable kernels for Tuesday](https://lwn.net/Articles/1106569/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Greg Kroah-Hartman 发布了 7.3.4、6.18.63 和 6.12.117 三个 stable 内核，分别包含超过 1250、860 和 1530 个补丁。建议相关用户尽快升级。</p><blockquote><p><strong>学习价值</strong>：可帮助学习者跟踪 stable 内核的发布节奏与补丁规模，了解内核维护的实际工作量。</p></blockquote><h3 id="_8b9cdfe472da-·-synaptics-patent-claims-stop-work-on-displaylink-drivers-1" tabindex="-1"><code>8b9cdfe472da</code> · <a href="https://lwn.net/Articles/1102549/" target="_blank" rel="noreferrer">[$] Synaptics patent claims stop work on DisplayLink drivers</a> <a class="header-anchor" href="#_8b9cdfe472da-·-synaptics-patent-claims-stop-work-on-displaylink-drivers-1" aria-label="Permalink to &quot;`8b9cdfe472da` · [[$] Synaptics patent claims stop work on DisplayLink drivers](https://lwn.net/Articles/1102549/)&quot;">​</a></h3><p><em>jzb｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>开发者 Mike Lothian 尝试借助 LLM 改进 Linux 上的 DisplayLink 驱动性能，并向已被 Synaptics 收购的 DisplayLink 团队求助。然而 Synaptics 法务团队以专利侵权为由要求其停止未经授权的 DisplayLink 技术实现并发出威胁，导致相关工作停滞。</p><blockquote><p><strong>学习价值</strong>：展示了专利与法律因素如何直接影响开源驱动的开发进程，是理解内核生态非技术层面约束的好案例。</p></blockquote><h3 id="_55fd90f794a9-·-firefox-160-released" tabindex="-1"><code>55fd90f794a9</code> · <a href="https://lwn.net/Articles/1106542/" target="_blank" rel="noreferrer">Firefox 160 released</a> <a class="header-anchor" href="#_55fd90f794a9-·-firefox-160-released" aria-label="Permalink to &quot;`55fd90f794a9` · [Firefox 160 released](https://lwn.net/Articles/1106542/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Firefox 160 发布，新特性包括阻止网站请求处理 mailto: 链接、支持播放含 FLAC/MP3/PCM 音轨的 Matroska 文件、画中画播放器速度控制，以及处于早期开发的 Mini Window 功能。</p><blockquote><p><strong>学习价值</strong>：与 Linux 内核无直接关系，对内核学习者价值有限。</p></blockquote><h3 id="f9c719f7bb1b-·-security-updates-for-tuesday" tabindex="-1"><code>f9c719f7bb1b</code> · <a href="https://lwn.net/Articles/1106522/" target="_blank" rel="noreferrer">Security updates for Tuesday</a> <a class="header-anchor" href="#f9c719f7bb1b-·-security-updates-for-tuesday" aria-label="Permalink to &quot;`f9c719f7bb1b` · [Security updates for Tuesday](https://lwn.net/Articles/1106522/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>AlmaLinux、Debian、Fedora 等发行版发布了大量安全更新，涉及 kernel、curl、glibc、nodejs、rust 相关包、python 等众多组件。用户应及时更新以修复已知漏洞。</p><blockquote><p><strong>学习价值</strong>：可关注其中 kernel 相关的安全更新，了解发行版如何回溯和分发内核安全补丁。</p></blockquote><h3 id="_50f2021fa005-·-amd-epyc-9686f-linux-benchmarks-96-zen-6-cores-at-up-to-5-3ghz" tabindex="-1"><code>50f2021fa005</code> · <a href="https://www.phoronix.com/review/amd-epyc-9686f" target="_blank" rel="noreferrer">AMD EPYC 9686F Linux Benchmarks: 96 Zen 6 Cores At Up To 5.3GHz</a> <a class="header-anchor" href="#_50f2021fa005-·-amd-epyc-9686f-linux-benchmarks-96-zen-6-cores-at-up-to-5-3ghz" aria-label="Permalink to &quot;`50f2021fa005` · [AMD EPYC 9686F Linux Benchmarks: 96 Zen 6 Cores At Up To 5.3GHz](https://www.phoronix.com/review/amd-epyc-9686f)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Phoronix 测试了 AMD EPYC 9686F，这是一款高频 Zen 6 处理器，具备 96 核 / 192 线程，量产版 boost 频率确认为 5.3GHz（高于最初公布的 5.0GHz）。</p><blockquote><p><strong>学习价值</strong>：硬件评测类新闻，对内核学习者的直接价值较低，仅作硬件趋势参考。</p></blockquote><h3 id="fe17c6bb4764-·-amd-talks-up-their-mext-software-amid-ram-crisis-linux-support-but-not-open-source" tabindex="-1"><code>fe17c6bb4764</code> · <a href="https://www.phoronix.com/news/AMD-MEXT" target="_blank" rel="noreferrer">AMD Talks Up Their MEXT Software Amid RAM Crisis - Linux Support But Not Open-Source</a> <a class="header-anchor" href="#fe17c6bb4764-·-amd-talks-up-their-mext-software-amid-ram-crisis-linux-support-but-not-open-source" aria-label="Permalink to &quot;`fe17c6bb4764` · [AMD Talks Up Their MEXT Software Amid RAM Crisis - Linux Support But Not Open-Source](https://www.phoronix.com/news/AMD-MEXT)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 收购的 MEXT 公司提供 AI 驱动的预测性内存技术，可将 NVMe SSD 等 flash 存储作为 DRAM 分层使用，以应对内存价格危机。该方案有 Linux 驱动支持，但并非开源，与 AMD 一贯的开源生态策略不同。</p><blockquote><p><strong>学习价值</strong>：涉及 flash-as-DRAM 分层这一内存管理热点方向，可引发对内核存储分层技术与开源许可模式的思考。</p></blockquote><h3 id="_50c19b423bee-·-amd-confirms-ace-with-7th-gen-epyc-florence-while-8th-gen-epyc-is-ravenna" tabindex="-1"><code>50c19b423bee</code> · <a href="https://www.phoronix.com/news/AMD-EPYC-Zen-7-Zen-8" target="_blank" rel="noreferrer">AMD Confirms ACE With 7th Gen EPYC &quot;Florence&quot; While 8th Gen EPYC Is &quot;Ravenna&quot;</a> <a class="header-anchor" href="#_50c19b423bee-·-amd-confirms-ace-with-7th-gen-epyc-florence-while-8th-gen-epyc-is-ravenna" aria-label="Permalink to &quot;`50c19b423bee` · [AMD Confirms ACE With 7th Gen EPYC &quot;Florence&quot; While 8th Gen EPYC Is &quot;Ravenna&quot;](https://www.phoronix.com/news/AMD-EPYC-Zen-7-Zen-8)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 在第六代 EPYC SP7 发布会上确认了后续路线图：第七代 EPYC 代号 &quot;Florence&quot; 将引入 ACE 架构，第八代则为 &quot;Ravenna&quot;。</p><blockquote><p><strong>学习价值</strong>：纯硬件路线图新闻，对内核学习者的直接价值有限。</p></blockquote><h3 id="_7a6fc0b35261-·-amd-epyc-embedded-9006-series-sp7-announced" tabindex="-1"><code>7a6fc0b35261</code> · <a href="https://www.phoronix.com/news/AMD-EPYC-Embedded-9006-Series" target="_blank" rel="noreferrer">AMD EPYC Embedded 9006 Series SP7 Announced</a> <a class="header-anchor" href="#_7a6fc0b35261-·-amd-epyc-embedded-9006-series-sp7-announced" aria-label="Permalink to &quot;`7a6fc0b35261` · [AMD EPYC Embedded 9006 Series SP7 Announced](https://www.phoronix.com/news/AMD-EPYC-Embedded-9006-Series)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>除 EPYC 9006 SP7 正式上市外，AMD 还同步宣布了面向嵌入式市场的 EPYC Embedded 9006 系列 SP7 处理器。</p><blockquote><p><strong>学习价值</strong>：嵌入式服务器处理器新闻，与内核开发关联较弱，仅作行业动态了解。</p></blockquote><h3 id="_9b0472424382-·-blender-5-3-released-with-nvidia-dlss-4-5-ray-reconstruction-vulkan-default" tabindex="-1"><code>9b0472424382</code> · <a href="https://www.phoronix.com/news/Blender-5.3-Released" target="_blank" rel="noreferrer">Blender 5.3 Released With NVIDIA DLSS 4.5 Ray Reconstruction, Vulkan Default</a> <a class="header-anchor" href="#_9b0472424382-·-blender-5-3-released-with-nvidia-dlss-4-5-ray-reconstruction-vulkan-default" aria-label="Permalink to &quot;`9b0472424382` · [Blender 5.3 Released With NVIDIA DLSS 4.5 Ray Reconstruction, Vulkan Default](https://www.phoronix.com/news/Blender-5.3-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Blender 5.3 发布，带来 NVIDIA DLSS 4.5 Ray Reconstruction 支持，并将 Vulkan 设为默认后端。</p><blockquote><p><strong>学习价值</strong>：属于图形应用软件新闻，与 Linux 内核学习基本无关。</p></blockquote><h3 id="ecab8c39e5ed-·-kora-announced-as-linux-desktop-os-for-the-age-of-intelligence" tabindex="-1"><code>ecab8c39e5ed</code> · <a href="https://www.phoronix.com/news/KORA-OS" target="_blank" rel="noreferrer">KORA Announced As Linux Desktop OS &quot;For The Age of Intelligence&quot;</a> <a class="header-anchor" href="#ecab8c39e5ed-·-kora-announced-as-linux-desktop-os-for-the-age-of-intelligence" aria-label="Permalink to &quot;`ecab8c39e5ed` · [KORA Announced As Linux Desktop OS &quot;For The Age of Intelligence&quot;](https://www.phoronix.com/news/KORA-OS)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>KORA Systems 发布了由 Samsung、Square Enix 等公司支持的 Linux 桌面发行版 KORA OS，定位为面向“智能 PC 时代”的操作系统。该消息属于发行版层面的产品发布，与内核子系统开发无直接关系。</p><blockquote><p><strong>学习价值</strong>：对内核学习者价值有限，仅可作为了解 Linux 生态中面向 AI PC 的新发行版动向的背景信息。</p></blockquote><h3 id="_5350b414e0aa-·-eight-more-security-issues-made-public-for-the-x-org-server-xwayland-1" tabindex="-1"><code>5350b414e0aa</code> · <a href="https://www.phoronix.com/news/Eight-More-XOrg-Server-Issues" target="_blank" rel="noreferrer">Eight More Security Issues Made Public For The X.Org Server / XWayland</a> <a class="header-anchor" href="#_5350b414e0aa-·-eight-more-security-issues-made-public-for-the-x-org-server-xwayland-1" aria-label="Permalink to &quot;`5350b414e0aa` · [Eight More Security Issues Made Public For The X.Org Server / XWayland](https://www.phoronix.com/news/Eight-More-XOrg-Server-Issues)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>在 AI/LLM 辅助下，X.Org Server 又有八个安全漏洞被公开披露，这些问题同样影响 XWayland 代码。这是近期 X.Org Server 一系列安全审计的延续。</p><blockquote><p><strong>学习价值</strong>：提醒学习者用户态图形栈的安全审计仍在持续，但内容不属于内核子系统本身。</p></blockquote><h3 id="fc7ece316574-·-longtime-linux-developer-steps-down-from-some-roles-due-to-patch-flood-caused-by-ai-1" tabindex="-1"><code>fc7ece316574</code> · <a href="https://www.phoronix.com/news/Lorenzo-Stoakes-AI-Flood" target="_blank" rel="noreferrer">Longtime Linux Developer Steps Down From Some Roles Due To Patch Flood Caused By AI</a> <a class="header-anchor" href="#fc7ece316574-·-longtime-linux-developer-steps-down-from-some-roles-due-to-patch-flood-caused-by-ai-1" aria-label="Permalink to &quot;`fc7ece316574` · [Longtime Linux Developer Steps Down From Some Roles Due To Patch Flood Caused By AI](https://www.phoronix.com/news/Lorenzo-Stoakes-AI-Flood)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Arm 的资深内存管理开发者 Lorenzo Stoakes（2014 年起贡献内核）宣布因 AI/LLM 生成补丁泛滥带来的噪音，将退出部分内核 reviewer 角色。这反映了 AI 生成补丁对内核维护流程的实际冲击。</p><blockquote><p><strong>学习价值</strong>：对学习者理解内核社区维护模式与 AI 冲击下的 reviewer 负担问题很有参考价值。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>7bf47f7e673a</code> · <a href="https://lore.kernel.org/all/20261111005533.6436-1-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v1 00/15] psp: introduce socket-less associations</a></li><li><code>38a87b771c9e</code> · <a href="https://lore.kernel.org/all/20261111002358.1842967-13-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v4 12/19] mm/shmem_luo: Retrieve tmpfs files into a file created by userspace</a></li></ul>',267)])])}const f=t(l,[["render",n]]);export{h as __pageData,f as default};
